('yks-2026-cografya#87', 'yks-2026-cografya', 'yks-2026-cografya#11', '11.3.7', 'Sanayileşmiş bir ülkeyi sanayileşme süreçleri açısından değerlendirir.', NULL, '[]'::jsonb, '{}'::jsonb, 87, 'meb_yks_2026', NULL, NULL, 'https://ttkb.meb.gov.tr/meb_iys_dosyalar/2025_11/26164023_2026_yks.pdf', 'meb_yks_2026', 'f52502743b6372e5df7de42d741b02a0b18eec087eac785b50a1fe3dd4a6d536', '2026-11-01T10:00:00+03:00'),
